const studioRequirementSearch = `-- name: StudioRequirementSearch :many
SELECT r.id, r.title
FROM studio_requirements r
JOIN studio_projects p ON p.tenant_id = r.tenant_id AND p.id = r.project_id
WHERE r.tenant_id = $1 AND r.project_id = $2 AND p.created_by = $3
  AND r.parent_id IS NULL AND NOT r.archived
  AND ($4::text = '' OR strpos(lower(r.title), lower($4::text)) > 0)
  AND ($5::bigint = 0 OR r.id <> $5::bigint)
ORDER BY r.id DESC
LIMIT 20
`

type StudioRequirementSearchParams struct {
	TenantID  string
	ProjectID int64
	CreatedBy int64
	Keyword   string
	Exclude   int64
}

type StudioRequirementSearchRow struct {
	ID    int64
	Title string
}

// Search top-level requirements for a parent selector. Children and archived
// nodes are not valid parents, so they never appear as candidates.
func (q *Queries) StudioRequirementSearch(ctx context.Context, arg StudioRequirementSearchParams) ([]StudioRequirementSearchRow, error) {
	rows, err := q.db.Query(ctx, studioRequirementSearch,
		arg.TenantID,
		arg.ProjectID,
		arg.CreatedBy,
		arg.Keyword,
		arg.Exclude,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []StudioRequirementSearchRow{}
	for rows.Next() {
		var i StudioRequirementSearchRow
		if err := rows.Scan(&i.ID, &i.Title); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const studioRequirementUpdate = `-- name: StudioRequirementUpdate :one
UPDATE studio_requirements r
SET title = $1,
    description = COALESCE($2::text, r.description),
    source = COALESCE($3::text, r.source),
    parent_id = CASE
      WHEN $4::bigint IS NULL THEN r.parent_id
      ELSE NULLIF($4::bigint, 0)
    END,
    updated_at = now()
FROM studio_projects p
WHERE r.tenant_id = $5
  AND r.id = $6
  AND r.project_id = $7
  AND r.project_id = p.id AND p.tenant_id = r.tenant_id
  AND p.created_by = $8
  AND r.archived = false
  AND ($4::bigint IS NULL OR $4::bigint = 0 OR EXISTS (
    SELECT 1 FROM studio_requirements parent
    WHERE parent.tenant_id = r.tenant_id AND parent.project_id = r.project_id
      AND parent.id = $4 AND parent.parent_id IS NULL AND NOT parent.archived
  ))
  AND ($4::bigint IS NULL OR $4::bigint = 0 OR NOT EXISTS (
    SELECT 1 FROM studio_requirements child
    WHERE child.tenant_id = r.tenant_id AND child.parent_id = r.id
  ))
RETURNING r.id, r.title, r.archived, r.parent_id
`

type StudioRequirementUpdateParams struct {
	Title       string
	Description pgtype.Text
	Source      pgtype.Text
	ParentID    pgtype.Int8
	TenantID    string
	ID          int64
	ProjectID   int64
	CreatedBy   int64
}

type StudioRequirementUpdateRow struct {
	ID       int64
	Title    string
	Archived bool
	ParentID pgtype.Int8
}

// Edit one requirement and optionally move it in the two-level tree. An
// archived requirement stays read-only, and the join guarantees the caller
// owns the parent project. Omitted description/source keep their stored text;
// an explicit empty string clears them. An omitted parent keeps the current
// node; 0 promotes it to a top-level requirement; another id moves it under
// that top-level requirement.
func (q *Queries) StudioRequirementUpdate(ctx context.Context, arg StudioRequirementUpdateParams) (StudioRequirementUpdateRow, error) {
	row := q.db.QueryRow(ctx, studioRequirementUpdate,
		arg.Title,
		arg.Description,
		arg.Source,
		arg.ParentID,
		arg.TenantID,
		arg.ID,
		arg.ProjectID,
		arg.CreatedBy,
	)
	var i StudioRequirementUpdateRow
	err := row.Scan(
		&i.ID,
		&i.Title,
		&i.Archived,
		&i.ParentID,
	)
	return i, err
}

